// What "the site is up" means: each page must answer 200 with its expected content, and the news
// sitemap must have a story from the last 48 hours (Google News reads it).
return [
  { json: { name: 'Portada', url: 'https://www.paddockintel.com/', must: '</html>' } },
  { json: { name: 'Feed', url: 'https://www.paddockintel.com/feed/', must: '</html>' } },
  { json: { name: 'Sitemap de noticias', url: 'https://www.paddockintel.com/sitemap-news.xml', must: '<urlset', freshHours: 48 } },
  { json: { name: 'Hub', url: 'https://hub.paddockintel.com/', must: '</html>' } },
];

// Emails only on a change: a check that fails twice in a row (about 20 minutes, so a single blip
// does not wake you up), and again when it recovers.
const targets = $('Targets').all().map((i) => i.json);
const state = $getWorkflowStaticData('global');
state.fails = state.fails || {}; state.down = state.down || {};
const nowIso = new Date().toISOString();
const newlyDown = []; const recovered = [];
$input.all().forEach((r, i) => {
  const t = targets[i]; if (!t) return;
  const body = String(r.json.body ?? r.json.data ?? '');
  let problem = '';
  if (r.json.error) problem = `sin respuesta (${r.json.error.message || r.json.error})`;
  else if (r.json.statusCode !== 200) problem = `HTTP ${r.json.statusCode}`;
  else if (!body.includes(t.must)) problem = 'responde 200 pero el contenido no está completo';
  else if (t.freshHours) {
    const dates = [...body.matchAll(/<news:publication_date>([^<]+)</g)].map((m) => Date.parse(m[1])).filter(Boolean);
    const newest = dates.length ? Math.max(...dates) : 0;
    const age = (Date.now() - newest) / 36e5;
    if (!newest) problem = 'el sitemap no tiene ninguna nota';
    else if (age > t.freshHours) problem = `la nota más reciente del sitemap tiene ${Math.round(age)} h`;
  }
  if (problem) {
    state.fails[t.name] = (state.fails[t.name] || 0) + 1;
    if (state.fails[t.name] === 2 && !state.down[t.name]) { state.down[t.name] = nowIso; newlyDown.push({ ...t, problem }); }
  } else {
    if (state.down[t.name]) { recovered.push({ ...t, since: state.down[t.name] }); delete state.down[t.name]; }
    state.fails[t.name] = 0;
  }
});
if (!newlyDown.length && !recovered.length) return [];
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;');
const li = (x) => `<li><b>${esc(x.name)}</b> (<a href="${esc(x.url)}">${esc(x.url)}</a>)${x.problem ? ': ' + esc(x.problem) : ' · caído desde ' + esc(x.since) + ' UTC'}</li>`;
const subject = newlyDown.length
  ? `⚠️ PaddockIntel: falla ${newlyDown.map((x) => x.name).join(', ')}`
  : `✅ PaddockIntel: recuperado ${recovered.map((x) => x.name).join(', ')}`;
return [{ json: { subject, html:
  (newlyDown.length ? `<p>Falló dos revisiones seguidas:</p><ul>${newlyDown.map(li).join('')}</ul>` : '') +
  (recovered.length ? `<p>Volvió a funcionar:</p><ul>${recovered.map(li).join('')}</ul>` : '') +
  `<p style="color:#888">Revisión cada 10 minutos desde el servidor de n8n.</p>` } }];
